#!/usr/bin/env python3
"""
NVE (Normalized Value-Eval ratio) Threshold Sensitivity Analysis

Reads the experiment registry, extracts NVE metrics, labels ground truth,
and computes classification performance at various NVE thresholds.
"""

import json
import math
from collections import OrderedDict

REGISTRY_PATH = "/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-9-projects-event-gated-adaptive-horizon/738d1ad5-83b9-408a-b880-7de8f3ac7af9/tool-results/mcp-agent-ml-research-read_registry-1779710700766.txt"
OUTPUT_PATH = "/home/ubuntu/.agent-ml-research-idea_gen_0509_9/projects/event-gated-adaptive-horizon/artifacts/plan_034_nve_threshold/analysis.md"

# =============================================================================
# 1. Load and parse registry
# =============================================================================
with open(REGISTRY_PATH) as f:
    raw = json.load(f)
inner = json.loads(raw['result'])
exps = inner['data']['experiments']

print(f"Total experiments in registry: {len(exps)}")

# =============================================================================
# 2. Define baseline VE ratios at each step (from exp_001_baseline for Walker)
# =============================================================================
# Walker Walk baseline (exp_001_baseline, seed 1): ve_ratio at each step
WALKER_BASELINE_VE = {
    '25K': 0.087, '35K': 0.241, '45K': 0.331, '55K': 0.404,
    '65K': 0.563, '75K': 0.719, '85K': 0.701, '95K': 0.632, '105K': 0.656
}

# Cheetah baseline: approximate from exp_023a/023b (ve_ratio ~ 0.5-0.7 range)
# exp_023b notes: ve_ratio_range 0.5-0.7; exp_023_cheetah_baseline_s3: ve_ratio_final=0.694
# exp_010a_cheetah_baseline_s1 doesn't have per-step VE. Use approximate values.
CHEETAH_BASELINE_VE = {
    '25K': 0.10, '35K': 0.20, '45K': 0.30, '55K': 0.40,
    '65K': 0.50, '75K': 0.55, '85K': 0.60, '95K': 0.65, '105K': 0.65
}

# Cartpole baseline: exp_060 only has eval_return_s2_105K=557, no per-step VE
# exp_062 has mean_ve_ratio_peak=0.071 (control), exp_061 has ve_ratio_peak=0.058
# Cartpole VE ratios are extremely low - not useful for NVE normalization
CARTPOLE_BASELINE_VE = {
    '105K': 0.05  # approximate
}


def parse_step_key(k):
    """Parse step keys like '105K', '55000', '105k', '85K' to integer steps."""
    k = k.strip().upper().replace(',', '')
    if k.endswith('K'):
        return int(float(k[:-1]) * 1000)
    return int(float(k))


def detect_env(exp_id, exp_data):
    """Detect environment from experiment id and data."""
    eid_lower = exp_id.lower()
    hyp = str(exp_data.get('hypothesis', '')).lower()
    spec_cmd = str(exp_data.get('spec', {}).get('command', '')).lower()

    if 'cheetah' in eid_lower or 'cheetah' in hyp or 'cheetah' in spec_cmd:
        return 'cheetah'
    if 'cartpole' in eid_lower or 'cartpole' in hyp or 'cartpole' in spec_cmd:
        return 'cartpole'
    if 'pickcube' in eid_lower or 'pickcube' in hyp or 'pickcube' in spec_cmd:
        return 'pickcube'
    if 'stackcube' in eid_lower or 'stackcube' in hyp or 'stackcube' in spec_cmd:
        return 'stackcube'
    if 'peginsertion' in eid_lower or 'peginsertion' in hyp or 'peginsertion' in spec_cmd:
        return 'peginsertion'
    # Default to walker for walker-related or generic experiments
    if 'walker' in eid_lower or 'walker' in hyp or 'walker' in spec_cmd:
        return 'walker'
    # Many experiments without env in name are walker
    return 'walker'


def detect_config(exp_id, exp_data):
    """Detect configuration type."""
    eid = exp_id.lower()
    hyp = str(exp_data.get('hypothesis', '')).lower()
    notes = str(exp_data.get('notes', '')).lower()

    if 'baseline' in eid or 'vanilla' in eid:
        return 'baseline'
    if 'frozen' in eid or 'frozen' in hyp or 'freeze' in hyp:
        return 'frozen_dt_emb'
    if '008f' in eid or 'no_dt_embed' in eid or 'no_dt_emb' in eid:
        return '008f_no_dt_emb'
    if '008e_v3' in eid or '008e_v3' in hyp:
        return '008e_v3_mitigation'
    if '008a' in eid:
        return '008a_unexposed'
    if '008d' in eid or 'civo_trigger' in eid:
        return '008d_civo_trigger'
    if '006' in eid:
        return '006_fixed_dt2'
    if 'dual_critic' in eid:
        return 'dual_critic'
    if 'sgs' in eid:
        return 'sgs'
    if 'tcn' in eid:
        return 'tcn'
    if 'rave' in eid:
        return 'rave'
    if 'gradient_stop' in eid:
        return 'gradient_stop'
    if 'trained' in eid:
        return 'trained_dt_emb'
    return 'other'


def detect_seed(exp_id, exp_data):
    """Extract seed from experiment id or spec."""
    eid = exp_id.lower()
    # Look for _s0, _s1, _s2, etc. patterns
    import re
    m = re.search(r'_s(\d+)(?:_|$)', eid)
    if m:
        return int(m.group(1))
    # Check spec command for --seed N
    spec_cmd = str(exp_data.get('spec', {}).get('command', ''))
    m = re.search(r'--seed\s+(\d+)', spec_cmd)
    if m:
        return int(m.group(1))
    return None


def get_baseline_ve(env):
    """Get baseline VE dict for an environment."""
    if env == 'cheetah':
        return CHEETAH_BASELINE_VE
    elif env == 'cartpole':
        return CARTPOLE_BASELINE_VE
    else:
        return WALKER_BASELINE_VE


def extract_peak_nve(exp_id, exp_data, env):
    """
    Extract peak NVE from experiment data.
    Returns (peak_nve, source_description) or (None, reason).

    Priority:
    1. Direct nve_peak field
    2. Compute from normalized_ve dict/fields
    3. Compute from value_eval_ratio / baseline_ve at matched steps
    4. Compute from ve_ratio / baseline_ve at matched steps
    """
    metrics = exp_data.get('metrics', {})
    if not isinstance(metrics, dict):
        return None, "no metrics dict"

    baseline_ve = get_baseline_ve(env)

    # --- Priority 1: Direct nve_peak field ---
    if 'nve_peak' in metrics:
        val = metrics['nve_peak']
        if isinstance(val, (int, float)):
            return float(val), "metrics.nve_peak"
        # Try to parse string like "< 1.5x" or "4.02"
        if isinstance(val, str):
            val_clean = val.strip().replace('x', '').replace('×', '')
            if val_clean.startswith('<'):
                # "< 1.5x" -> use 1.49 as approximate upper bound
                try:
                    return float(val_clean[1:].strip()) - 0.01, f"metrics.nve_peak (parsed '{val}')"
                except:
                    pass
            try:
                return float(val_clean), f"metrics.nve_peak (parsed '{val}')"
            except:
                pass

    # Check for nve in sub-fields like nve_105K, nve_95K etc.
    nve_step_vals = {}
    for k, v in metrics.items():
        if k.startswith('nve_') and k != 'nve_peak' and k != 'nve_classification' and k != 'nve_note' and not k.startswith('nve_peak_') and not k.startswith('nve_onset') and not k.startswith('nve_final') and not k.startswith('nve_sustained') and not k.startswith('nve_classification') and not k.startswith('nve_initial'):
            if isinstance(v, (int, float)):
                nve_step_vals[k] = float(v)

    # Also check nve_final
    for fld in ['nve_final', 'nve_final_105k', 'final_nve']:
        if fld in metrics and isinstance(metrics[fld], (int, float)):
            nve_step_vals[fld] = float(metrics[fld])

    # --- Priority 2: normalized_ve dict ---
    if 'normalized_ve' in metrics:
        nve_data = metrics['normalized_ve']
        if isinstance(nve_data, dict):
            max_nve = 0
            max_step = None
            for step_key, val in nve_data.items():
                if isinstance(val, (int, float)):
                    if float(val) > max_nve:
                        max_nve = float(val)
                        max_step = step_key
            if max_nve > 0:
                return max_nve, f"max(metrics.normalized_ve) at {max_step}"

    # Check normalized_ve_XXK fields
    nve_from_fields = {}
    for k, v in metrics.items():
        if k.startswith('normalized_ve_') and isinstance(v, (int, float)):
            nve_from_fields[k] = float(v)
    if nve_from_fields:
        max_k = max(nve_from_fields, key=nve_from_fields.get)
        return nve_from_fields[max_k], f"max({max_k})"

    # If we found nve step values from priority 1b
    if nve_step_vals:
        max_k = max(nve_step_vals, key=nve_step_vals.get)
        return nve_step_vals[max_k], f"max({max_k})"

    # --- Priority 3: Compute from value_eval_ratio / baseline ---
    ve_ratios = {}

    # Check value_eval_ratio dict
    if 'value_eval_ratio' in metrics and isinstance(metrics['value_eval_ratio'], dict):
        for step_key, val in metrics['value_eval_ratio'].items():
            if isinstance(val, (int, float)):
                ve_ratios[step_key] = float(val)

    # Check value_eval_ratio_XXK fields
    for k, v in metrics.items():
        if k.startswith('value_eval_ratio_') and not k.endswith('stable'):
            if isinstance(v, (int, float)):
                step_key = k.replace('value_eval_ratio_', '')
                ve_ratios[step_key] = float(v)
            elif isinstance(v, str):
                # Try to parse "41.1%" or "0.656"
                try:
                    v_clean = v.strip().replace('%', '')
                    fv = float(v_clean)
                    if fv > 1 and '%' in v:
                        fv /= 100.0
                    step_key = k.replace('value_eval_ratio_', '')
                    ve_ratios[step_key] = fv
                except:
                    pass

    # Check ve_ratio fields
    if 've_ratio_trajectory' in metrics and isinstance(metrics['ve_ratio_trajectory'], dict):
        for step_key, val in metrics['ve_ratio_trajectory'].items():
            if isinstance(val, (int, float)):
                ve_ratios[step_key] = float(val)
    elif 've_ratio_trajectory' in metrics and isinstance(metrics['ve_ratio_trajectory'], list):
        for item in metrics['ve_ratio_trajectory']:
            if isinstance(item, dict) and 'step' in item and 've' in item:
                step_key = str(item['step'])
                ve_ratios[step_key] = float(item['ve'])

    for k, v in metrics.items():
        if k == 've_ratio_peak' and isinstance(v, (int, float)):
            # We have peak ve_ratio but need to normalize by baseline
            # Try to find the step
            peak_step = metrics.get('ve_ratio_peak_step', None)
            if peak_step:
                step_key = str(peak_step)
                ve_ratios[step_key] = float(v)

    # Check eval_checkpoints structure (like 008f)
    if 'eval_checkpoints' in metrics and isinstance(metrics['eval_checkpoints'], dict):
        for step_key, checkpoint in metrics['eval_checkpoints'].items():
            if isinstance(checkpoint, dict):
                if 'normalized_ve' in checkpoint:
                    nve_from_fields[step_key] = float(checkpoint['normalized_ve'])
                if 've_ratio' in checkpoint:
                    ve_ratios[step_key] = float(checkpoint['ve_ratio'])
        if nve_from_fields:
            max_k = max(nve_from_fields, key=nve_from_fields.get)
            return nve_from_fields[max_k], f"max(eval_checkpoints.normalized_ve) at {max_k}"

    # Now compute NVE = ve_ratio / baseline_ve for each matched step
    if ve_ratios:
        max_nve = 0
        max_step = None
        for step_key, ve in ve_ratios.items():
            # Normalize step key
            try:
                step_val = parse_step_key(step_key)
            except:
                continue
            # Find matching baseline step
            normalized_key = f"{step_val // 1000}K"
            if normalized_key in baseline_ve and baseline_ve[normalized_key] > 0.05:
                nve = ve / baseline_ve[normalized_key]
                if nve > max_nve:
                    max_nve = nve
                    max_step = normalized_key
        if max_nve > 0:
            return max_nve, f"computed ve_ratio/baseline at {max_step}"

    # --- Priority 4: Use ve_ratio_peak / baseline if available ---
    if 've_ratio_peak' in metrics and isinstance(metrics['ve_ratio_peak'], (int, float)):
        ve_peak = float(metrics['ve_ratio_peak'])
        peak_step = metrics.get('ve_ratio_peak_step', None)
        if peak_step:
            try:
                step_val = parse_step_key(str(peak_step))
                normalized_key = f"{step_val // 1000}K"
                if normalized_key in baseline_ve and baseline_ve[normalized_key] > 0.05:
                    return ve_peak / baseline_ve[normalized_key], f"computed ve_ratio_peak/baseline at {normalized_key}"
            except:
                pass
        # Fall back: use max baseline ve as denominator (conservative)
        max_baseline = max(baseline_ve.values())
        if max_baseline > 0:
            return ve_peak / max_baseline, f"computed ve_ratio_peak/max_baseline_ve"

    # Check civo_ve_ratio_final for 008a experiments
    if 'civo_ve_ratio_final' in metrics:
        ve = float(metrics['civo_ve_ratio_final'])
        max_baseline = max(baseline_ve.values())
        if max_baseline > 0:
            return ve / max_baseline, f"computed civo_ve_ratio_final/max_baseline_ve"

    return None, "no VE/NVE data found"


# =============================================================================
# 3. Ground truth labeling
# =============================================================================
def label_ground_truth(exp_id, exp_data, env, peak_nve):
    """
    Label ground truth:
    - 1 = CIVO collapsed
    - 0 = Healthy (no CIVO)
    - None = EXCLUDE
    """
    conclusion = exp_data.get('conclusion', 'N/A')
    metrics = exp_data.get('metrics', {})
    if not isinstance(metrics, dict):
        metrics = {}
    notes = str(exp_data.get('notes', '')).lower()
    verdict = str(metrics.get('verdict', '') or exp_data.get('verdict', '')).lower()
    nve_class = str(metrics.get('nve_classification', '')).lower()

    # EXCLUDE: technical failures
    if conclusion in ('killed', 'failed'):
        return None, "technical failure"

    # EXCLUDE: status not done/complete
    status = exp_data.get('status', '')
    if status in ('ALLOCATED', 'RUNNING', 'SUBMITTED') and conclusion == 'N/A':
        return None, "not completed"

    # EXCLUDE: baselines (they are the reference, not classification samples)
    config = detect_config(exp_id, exp_data)
    if config == 'baseline':
        return None, "baseline (reference)"

    # EXCLUDE: experiments without NVE data
    if peak_nve is None:
        return None, "no NVE data"

    # --- Explicit CIVO collapsed ---
    # 008d CIVO trigger experiments (trained dt_emb + subsample ON + H=8)
    civo_positive_ids = {
        'exp_006_fixed_dt2',  # conclusion=negative, VE accelerating to 2.722
        'exp_008d_subsample_on_h8',  # verdict COLLAPSE_CONFIRMED, VE=1.666
        'exp_008d_civo_trigger_s3',  # nve_classification=onset_collapse, nve=1.53
        'exp_008d_civo_trigger_s4',  # nve_classification=onset_collapse, nve=4.62
        'exp_009e_008d_walker_s1',  # nve_classification=onset_collapse, nve=4.13
        'exp_068_008d_walker_repro_s1',  # nve_peak=6.57, eval crashed to 39.1
        'exp_009b_008d_walker_s2',  # nve_classification=onset_self_correcting but nve peaked 1.62
        'exp_059_walker_trained_s5',  # nve_classification=onset_collapse, nve=4.72
        'exp_008e_v3_walker_s2',  # collapsed: nve=3.78, eval crashed 715->137
        'exp_008e_v3_s3',  # collapsed: nve=4.02, eval crashed 520->93
        'exp_010b_cheetah_civo_trigger_s0',  # cheetah CIVO: nve_105K=70.64
        'exp_010b_cheetah_civo_trigger',  # cheetah CIVO: nve_peak=8.27
        'exp_048_cheetah_civo_extension',  # cheetah CIVO extension: nve=70.64 initially
        'exp_045_treatment_extension_008d_s3',  # nve_peak=4.91 (then recovered in extension)
    }

    # Healthy experiments (no CIVO)
    healthy_ids = {
        'exp_008a_no_subsample_dt2',  # success, max normalized_ve=0.93
        'exp_008a_unexposed_s1',  # success, civo_ve_ratio_final=0.43
        'exp_008a_unexposed_s2',  # success, civo_ve_ratio_final=0.333
        'exp_008a_cheetah_unexposed_s0',  # success, nve_105k=0.49
        'exp_008a_cheetah_unexposed_s1',  # success, nve_105k=0.478
        'exp_008e_v3_subsample_on_dt1_h15',  # success, normalized_ve stable 0.72-0.80
        'exp_008e_v3_walker_s1',  # success, ve_ratio=0.527
        'exp_008e_v3_s4',  # success, nve_peak=0.99
        'exp_072_008e_v3_walker_s5',  # success, nve_peak=0.61
        'exp_008f_no_dt_embed_subsample_on_h8',  # success, max normalized_ve=1.02 (transient)
        'exp_008f_s3_no_dt_embed_walker',  # success, nve_peak < 1.5
        'exp_008f_s4',  # negative but nve=1.41 (below CIVO)
        'exp_043_008f_walker_s1',  # success, nve_peak=0.808
        'exp_069_008f_walker_repro_s1',  # success, nve_peak=0.66
        'exp_071_008f_walker_s3',  # success, ve_ratio_peak=0.7
        'exp_073_008f_walker_s4',  # success, nve_peak=0.76
        'exp_042_frozen_dt_emb_walker',  # success, nve_peak=0.194
        'exp_015b_frozen_dt_emb',  # frozen, nve_105K=0.42
        'exp_046_frozen_dt_emb_cheetah',  # success, nve_peak=1.35
        'exp_058_frozen_dt_emb_cheetah_s1',  # nve_peak=0.78
        'exp_047_frozen_dt_emb_walker_s1',  # nve_peak=1.71 but conclusion=success, transient
        'exp_057_frozen_dt_emb_walker_s2',  # nve_classification=transient, nve_peak=1.88
        'exp_020_vanilla_dreamerv3_s2',  # vanilla baseline-like, ve_ratio=0.645
        'exp_009c_008f_walker_s2',  # negative but nve=1.14 (no delusional critic per verdict)
        'exp_070_008e_v3_walker_s0',  # negative but NOT via CIVO per notes, nve=0.8
    }

    if exp_id in civo_positive_ids:
        return 1, "CIVO collapsed (manual label)"
    if exp_id in healthy_ids:
        return 0, "Healthy (manual label)"

    # --- Heuristic labeling for remaining experiments ---
    # Check nve_classification field
    if nve_class in ('onset_collapse',):
        return 1, f"nve_classification={nve_class}"
    if nve_class in ('no_civo', 'transient'):
        return 0, f"nve_classification={nve_class}"

    # Check verdict
    if 'collapse' in verdict and 'no' not in verdict:
        return 1, f"verdict contains 'collapse'"
    if 'success' in verdict and 'civo' not in verdict.replace('no civo', '').replace('no_civo', ''):
        return 0, f"verdict=success"

    # Check conclusion + NVE heuristic
    if conclusion == 'negative' and peak_nve is not None and peak_nve > 2.0:
        return 1, f"conclusion=negative + peak_nve={peak_nve:.2f} > 2.0"
    if conclusion == 'success' and peak_nve is not None and peak_nve < 1.2:
        return 0, f"conclusion=success + peak_nve={peak_nve:.2f} < 1.2"

    return None, "ambiguous classification"


# =============================================================================
# 4. Build dataset
# =============================================================================
dataset = []
excluded = []

for exp_id, exp_data in exps.items():
    env = detect_env(exp_id, exp_data)
    config = detect_config(exp_id, exp_data)
    seed = detect_seed(exp_id, exp_data)
    conclusion = exp_data.get('conclusion', 'N/A')

    peak_nve, nve_source = extract_peak_nve(exp_id, exp_data, env)
    label, label_reason = label_ground_truth(exp_id, exp_data, env, peak_nve)

    entry = {
        'exp_id': exp_id,
        'env': env,
        'config': config,
        'seed': seed,
        'conclusion': conclusion,
        'peak_nve': peak_nve,
        'nve_source': nve_source,
        'ground_truth': label,
        'label_reason': label_reason,
    }

    if label is not None:
        dataset.append(entry)
    else:
        excluded.append(entry)

# Sort dataset by exp_id
dataset.sort(key=lambda x: x['exp_id'])
excluded.sort(key=lambda x: x['exp_id'])

print(f"\nDataset: {len(dataset)} samples")
print(f"  Collapsed (1): {sum(1 for d in dataset if d['ground_truth'] == 1)}")
print(f"  Healthy (0): {sum(1 for d in dataset if d['ground_truth'] == 0)}")
print(f"Excluded: {len(excluded)} experiments")

# =============================================================================
# 5. Classification at various NVE thresholds
# =============================================================================
thresholds = [1.0, 1.1, 1.2, 1.3, 1.5, 1.7, 2.0]

results = []
for thresh in thresholds:
    tp = fp = tn = fn = 0
    for d in dataset:
        predicted = 1 if d['peak_nve'] >= thresh else 0
        actual = d['ground_truth']
        if predicted == 1 and actual == 1:
            tp += 1
        elif predicted == 1 and actual == 0:
            fp += 1
        elif predicted == 0 and actual == 0:
            tn += 1
        elif predicted == 0 and actual == 1:
            fn += 1

    precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0
    accuracy = (tp + tn) / len(dataset) if len(dataset) > 0 else 0.0

    results.append({
        'threshold': thresh,
        'TP': tp, 'FP': fp, 'TN': tn, 'FN': fn,
        'Precision': precision, 'Recall': recall, 'F1': f1, 'Accuracy': accuracy,
    })

# =============================================================================
# 6. AUROC computation (trapezoidal rule)
# =============================================================================
auroc = None
auroc_note = ""

if len(dataset) >= 10:
    positives = [d['peak_nve'] for d in dataset if d['ground_truth'] == 1]
    negatives = [d['peak_nve'] for d in dataset if d['ground_truth'] == 0]

    if len(positives) > 0 and len(negatives) > 0:
        # Generate ROC curve points at many thresholds
        all_nve = sorted(set([d['peak_nve'] for d in dataset]), reverse=True)
        # Add endpoints
        roc_thresholds = [max(all_nve) + 1.0] + all_nve + [min(all_nve) - 1.0]

        roc_points = []  # (FPR, TPR)
        for t in roc_thresholds:
            tp = sum(1 for v in positives if v >= t)
            fp = sum(1 for v in negatives if v >= t)
            tpr = tp / len(positives)
            fpr = fp / len(negatives)
            roc_points.append((fpr, tpr))

        # Sort by FPR, then TPR
        roc_points.sort(key=lambda x: (x[0], x[1]))

        # Remove duplicates keeping max TPR for each FPR
        unique_fpr = OrderedDict()
        for fpr, tpr in roc_points:
            if fpr not in unique_fpr or tpr > unique_fpr[fpr]:
                unique_fpr[fpr] = tpr
        roc_points = [(fpr, tpr) for fpr, tpr in unique_fpr.items()]

        # Trapezoidal AUC
        auroc = 0.0
        for i in range(1, len(roc_points)):
            x0, y0 = roc_points[i-1]
            x1, y1 = roc_points[i]
            auroc += (x1 - x0) * (y0 + y1) / 2.0

        auroc_note = f"Computed from {len(positives)} positive + {len(negatives)} negative samples using {len(roc_points)} ROC points"
    else:
        auroc_note = f"Cannot compute: {len(positives)} positives, {len(negatives)} negatives"
